/**
 * Hand-written English sentences naming typical (fictitious) US and UK people,
 * companies, and projects. Every entry is declared only by its full name, the way
 * a user would type it; each sentence must be masked with that entry's symbol.
 */
export interface EnglishCase { id: string; cls: string; term: string; sentences: string[] }

const P = (id: string, term: string, sentences: string[]): EnglishCase => ({ id, cls: 'PERSON', term, sentences })
const C = (id: string, term: string, sentences: string[], cls = 'COMPANY'): EnglishCase => ({ id, cls, term, sentences })

